int k = values[1];
int[] a = new int[values.Length - 2];
Array.Copy(values, 2, a, 0, a.Length);

int[] dp = new int[n];
Array.Fill(dp, 1);
int answer = 0;
for (int i = 0; i < n; i++) {
    for (int j = 0; j < i; j++) {
        if (a[j] < a[i]) {
