const fs = require("node:fs");
const values = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);
const [n, k] = values;
const a = values.slice(2);

let dp = Array(n).fill(1);
let answer = 0;
for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
        if (a[j] < a[i]) {
            dp[i] = Math.max(dp[i], dp[j] + 1);
        }
    }
    answer = Math.max(answer, dp[i]);
}
console.log(answer);

