Объяснение строки показывает её роль в записи. Чтобы проследить выполнение ветки или цикла, используй конкретный вход и таблицу состояния: при выполнении одна строка может повториться несколько раз или не выполниться вовсе.

examples:
const fs = require("node:fs");
const values = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);
const [n, k] = values;
const a = values.slice(2);

let distance = Array(n).fill(-1);
let queue = Array(n).fill(0);
let head = 0;
let tail = 0;
distance[k] = 0;
queue[tail] = k;
tail++;
while (head < tail) {
    let vertex = queue[head];
    head++;
    for (let next = 0; next < n; next++) {
        if (a[vertex * n + next] !== 0 && distance[next] === -1) {
            distance[next] = distance[vertex] + 1;
            queue[tail] = next;
            tail++;
        }
    }
}
for (let i = 0; i < n; i++) {
    console.log(distance[i]);
}

