    out := bufio.NewWriter(os.Stdout)
    defer out.Flush()
    var n, k int
    if _, err := fmt.Fscan(in, &n, &k); err != nil { return }
    a := []int{}
    for {
        var value int
        if _, err := fmt.Fscan(in, &value); err != nil { break }
        a = append(a, value)
    }
    _ = k
    left := 0;
    total := 0;
    best := 0;
    for right := 0; right < n; right++ {
        total += a[right];
        for (left <= right && total > k) {
            total -= a[left];
            left++;
        }
        best = max(best, right - left + 1);
    }
    fmt.Fprintln(out, best);
}

